macros.command:
// Fills SoundBard banks with this adventure's cues (SoundBard keeps banks per browser, so each GM who wants
// the pads runs this once). Re-running it refreshes the same banks.
if (!game.modules.get("soundbard")?.active) return ui.notifications.warn("Enable the SoundBard module first.");
const BANKS = {"The Back Room: Corridors": [["Door, slowly", "modules/soundfxlibrary/Misc/Single/Squeaky Door Open Slow/squeaky-door-open-slow-1.mp3", "🚪", 0.7, false], ["A door closes somewhere", "modules/soundfxlibrary/Misc/Single/Door Close/door-close-1.mp3", "🔒", 0.6, false], ["Footsteps, a half-beat late", "modules/the-back-room/audio/sting-footsteps.ogg", "👣", 0.7, false], ["The X", "modules/the-back-room/audio/sting-x-door.ogg", "❌", 0.7, false], ["The lantern lights itself", "modules/soundfxlibrary/Combat/Single/Spell Whoosh/spell-whoosh-1.mp3", "🏮", 0.5, false], ["Waterfall (stops when someone speaks)", "modules/soundfxlibrary/Nature/Loops/Waterfall/waterfall-1.mp3", "🌊", 0.5, true], ["The ferry bell", "modules/the-back-room/audio/sfx-ferry-bell.ogg", "🔔", 0.7, false], ["A horse shifts its weight", "modules/soundfxlibrary/Creatures/Animals/Horse Whinny/horse-whinny-2.mp3", "🐴", 0.5, false], ["Pages turning", "modules/the-back-room/audio/sfx-pages-turning.ogg", "📖", 0.7, false], ["Dice, warm, just rolled", "modules/the-back-room/audio/sfx-dice-rolled.ogg", "🎲", 0.7, false], ["A monster wakes (The Cover)", "modules/soundfxlibrary/Creatures/Monsters/Growl/growl-3.mp3", "🐉", 0.7, false], ["Cider, poured", "modules/the-back-room/audio/sfx-cider-poured.ogg", "🍺", 0.7, false]], "The Back Room: People": [["Remnants laughing, through the door", "modules/the-back-room/audio/sfx-remnants-laughing.ogg", "😂", 0.4, false], ["POW! (Fred)", "modules/soundfxlibrary/Combat/Single/Melee Hit/melee-hit-7.mp3", "💥", 0.8, false], ["Rorvik bursts in", "modules/soundfxlibrary/Misc/Single/Impact/impact-2.mp3", "⏰", 0.8, false], ["Strider's arrow", "modules/soundfxlibrary/Combat/Single/Arrow Fly-By/arrow-fly-by-1.mp3", "🏹", 0.7, false], ["Thon's rod clicks into a new shape", "modules/soundfxlibrary/Combat/Single/Shield Hit/shield-hit-3.mp3", "🔧", 0.6, false], ["T. Morlock lands a vault", "modules/soundfxlibrary/Combat/Single/Throw Hit/throw-hit-1.mp3", "🤸", 0.6, false]]};
const data = foundry.utils.deepClone(game.settings.get("soundbard", "soundBank"));
const done = [];
for (const [name, pads] of Object.entries(BANKS)) {
  let bank = data.banks.find(b => b.name === name) ?? data.banks.find(b => !b.name && b.slots.every(s => !s.src));
  if (!bank) { ui.notifications.warn(`SoundBard has no empty bank left for "${name}"; clear one and run this again.`); continue; }
  bank.name = name;
  bank.slots.forEach((slot, i) => Object.assign(slot, pads[i] ? { name: pads[i][0], src: pads[i][1], emoji: pads[i][2], volume: pads[i][3], loop: pads[i][4] } : { name: "", src: "", emoji: "" }));
  done.push(bank);
}
await game.settings.set("soundbard", "soundBank", data);
if (done[0]) await game.settings.set("soundbard", "activeBank", done[0].id);
ui.notifications.info(`SoundBard: ${done.map(b => `bank ${b.id} "${b.name}"`).join(", ")}.`);

// Deletes exactly the documents this adventure imported (matched by id against the adventure in the compendium).
// Your own documents are left alone. SoundBard banks the setup macro filled stay in SoundBard.
const pack = game.packs.get("the-back-room.the-back-room-unfinished");
if (!pack) return ui.notifications.error("Enable The Back Room module first.");
const ok = await foundry.applications.api.DialogV2.confirm({ window: { title: "Remove The Back Room: The Unfinished Fight" },
  content: "<p>Delete every scene, actor, journal, playlist, roll table, macro and folder this adventure imported? Your own documents are left alone.</p>" });
if (!ok) return;
const [adv] = await pack.getDocuments();
const types = { scenes: "Scene", actors: "Actor", journal: "JournalEntry", items: "Item", tables: "RollTable", macros: "Macro", playlists: "Playlist", cards: "Cards", folders: "Folder" };
const counts = [];
for (const [field, cls] of Object.entries(types)) {
  const ids = new Set(adv[field]?.map(d => d.id) ?? []);
  const found = game.collections.get(cls).filter(d => ids.has(d.id));
  if (cls === "Playlist") for (const p of found) if (p.playing) await p.stopAll();
  if (found.length) { await getDocumentClass(cls).deleteDocuments(found.map(d => d.id)); counts.push(`${found.length} ${cls}`); }
}
ui.notifications.info(`Removed: ${counts.join(", ") || "nothing (the adventure is not imported here)"}.`);
